"""Load only artifacts generated by you: joblib/pickle loading can execute code."""
from pathlib import Path
import joblib
import numpy as np
from .data import normalize_tags


class Predictor:
    def __init__(self, artifact: str | Path):
        payload = joblib.load(artifact)
        if not isinstance(payload, dict) or "pipeline" not in payload or "report" not in payload:
            raise ValueError("Unrecognized model artifact")
        self.pipeline = payload["pipeline"]
        self.report = payload["report"]
        self.vocabulary = set(self.pipeline.named_steps["tags"].vocabulary_)

    def predict(self, tags: list[str]) -> dict:
        if not 1 <= len(tags) <= 64:
            raise ValueError("Provide between 1 and 64 tags")
        if any(not isinstance(tag, str) or len(tag) > 100 or "|" in tag for tag in tags):
            raise ValueError("Each tag must be a string of up to 100 characters, without pipes")
        normalized = normalize_tags("|".join(tags))
        known = sorted(set(normalized) & self.vocabulary)
        unknown = sorted(set(normalized) - self.vocabulary)
        if not known:
            raise ValueError("None of these tags were observed in training; use at least one known tag")
        rating = float(np.clip(self.pipeline.predict(["|".join(normalized)])[0], 0, 10))
        if not np.isfinite(rating):
            raise ValueError("The model produced a non-finite value")
        return {"predicted_rating": round(rating, 3), "scale": [0, 10],
                "model": self.report["selected_model"], "known_tags": known,
                "unknown_tags": unknown, "dataset_kind": self.report["dataset_kind"]}
